## The retry utility

**`src/lib/retry.js`** (or wherever you keep shared utils)

```js
/**
 * Retry an async function with exponential backoff.
 *
 * @param {() => Promise<T>} fn  – the async operation to attempt
 * @param {object}  opts
 * @param {number}  [opts.retries=3]      – max *additional* attempts after the first
 * @param {number}  [opts.baseDelay=200]  – ms before the 1st retry (doubles each time)
 * @param {number}  [opts.maxDelay=10_000]– cap on a single backoff sleep
 * @param {(err: Error, attempt: number) => boolean} [opts.shouldRetry]
 *        – return false to bail early (e.g. on 4xx). Default: retry everything.
 * @returns {Promise<T>}
 */
export async function retry(fn, opts = {}) {
  const {
    retries = 3,
    baseDelay = 200,
    maxDelay = 10_000,
    shouldRetry = () => true,
  } = opts;

  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      return await fn();
    } catch (err) {
      lastError = err;

      // Don't sleep after the final attempt.
      if (attempt === retries || !shouldRetry(err, attempt)) {
        break;
      }

      const delay = Math.min(baseDelay * 2 ** attempt, maxDelay);
      // Add ±20 % jitter so concurrent callers don't stampede.
      const jittered = delay * (1 + (Math.random() - 0.5) * 0.4);

      await new Promise((resolve) => setTimeout(resolve, jittered));
    }
  }

  throw lastError;
}
```

